window.__PHD.push(" \"chinese_or_csc\": null, \"note\": \"\u4ea6\u53c2\u4e0e Design Museum Pop-up VR \u7528\u6237\u6d4b\u8bd5\"}, {\"name\": \"F. C. Souza Leite\", \"status\": \"alumni\", \"graduation_year\": 2022, \"thesis_title\": \"Enabling Cost Efficiency in Sensor-Based Human Activity Recognition\", \"topic_zh\": \"\u4f4e\u6210\u672c\u4f20\u611f\u5668\u4eba\u7c7b\u6d3b\u52a8\u8bc6\u522b\", \"url\": \"https://research.aalto.fi/en/publications/enabling-cost-efficiency-in-sensor-based-human-activity-recogniti/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Daniel H. Landau\", \"status\": \"alumni\", \"graduation_year\": 2020, \"thesis_title\": \"Becoming Other: Virtual Embodiment - Blurring the Self-Other Binary\", \"topic_zh\": \"VR \u4e2d\u7684\u865a\u62df\u5177\u8eab\u4e0e\u81ea\u6211-\u4ed6\u8005\u8fb9\u754c\uff08\u827a\u672f\u5b9e\u8df5\u578b\uff09\", \"url\": \"https://research.aalto.fi/en/publications/becoming-other-virtual-embodiment-blurring-the-self-other-binary/\", \"now\": null, \"background\": \"\u5a92\u4f53\u827a\u672f/VR \u521b\u4f5c\u8005\", \"chinese_or_csc\": null}, {\"name\": \"Massimo Menichinelli\", \"status\": \"alumni\", \"graduation_year\": 2020, \"thesis_title\": \"Open and collaborative design processes: Meta-Design, ontologies and platforms within the Maker Movement\", \"topic_zh\": \"\u521b\u5ba2\u8fd0\u52a8\u4e2d\u7684\u5f00\u653e\u534f\u4f5c\u8bbe\u8ba1\u3001\u5143\u8bbe\u8ba1\u4e0e\u672c\u4f53\", \"url\": \"https://research.aalto.fi/en/publications/open-and-collaborative-design-processes-meta-design-ontologies-an/\", \"now\": null, \"background\": \"\u8bbe\u8ba1\", \"chinese_or_csc\": null}, {\"name\": \"K. Klouche\", \"status\": \"alumni\", \"graduation_year\": 2019, \"thesis_title\": \"Explorable Information Spaces: Designing Entity Affordances for Fluid Information Exploration\", \"topic_zh\": \"\u53ef\u63a2\u7d22\u4fe1\u606f\u7a7a\u95f4\u4e0e\u4fe1\u606f\u53ef\u89c6\u5316\u4ea4\u4e92\u8bbe\u8ba1\", \"url\": \"https://research.aalto.fi/en/publications/explorable-information-spaces-designing-entity-affordances-for-fl/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Sanna Marttila\", \"status\": \"alumni\", \"graduation_year\": 2018, \"thesis_title\": \"Infrastructuring for cultural commons\", \"topic_zh\": \"\u6587\u5316\u516c\u5730\uff08\u6570\u5b57\u6587\u5316\u9057\u4ea7\u5f00\u653e\u8d44\u6e90\uff09\u7684\u57fa\u7840\u8bbe\u65bd\u5316\uff0c\u53c2\u4e0e\u5f0f\u8bbe\u8ba1\", \"url\": \"https://interaccio.diba.cat/sites/interaccio.diba.cat/files/marttila.pdf\", \"now\": null, \"background\": \"\u8bbe\u8ba1\u7814\u7a76\", \"chinese_or_csc\": null}, {\"name\": \"P. \u00c5man\", \"status\": \"alumni\", \"graduation_year\": 2018, \"thesis_title\": \"Musical serendipity: Designing for contextual music recommendation and discovery\", \"topic_zh\": \"\u60c5\u5883\u5316\u97f3\u4e50\u63a8\u8350\u4e0e\u53d1\u73b0\u7684\u8bbe\u8ba1\", \"url\": \"https://research.aalto.fi/en/publications/musical-serendipity-designing-for-contextual-music-recommendation/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"S. Bhowmik\", \"status\": \"alumni\", \"graduation_year\": 2016, \"thesis_title\": \"Deep time of the museum: the materiality of media infrastructures\", \"topic_zh\": \"\u535a\u7269\u9986\u7684\u6df1\u65f6\u95f4\uff1a\u5a92\u4ecb\u57fa\u7840\u8bbe\u65bd\u7684\u7269\u8d28\u6027\", \"url\": \"https://research.aalto.fi/en/publications/deep-time-of-the-museum-the-materiality-of-media-infrastructures/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"Pure \u767b\u8bb0\u5df2\u6bd5\u4e1a\u535a\u58eb 21 \u7bc7\uff082009\u20132026\uff0c\u8fd1 10 \u5e74\u7ea6 12\uff09\uff1b\u5728\u8bfb\u4eba\u6570\u672a\u516c\u5f00\", \"student_pattern_zh\": \"\u5a92\u4f53\u5b9e\u9a8c\u5ba4 Systems of Representation \u7ec4\uff1a\u5b66\u751f\u8bfe\u9898\u6a2a\u8de8\u6570\u5b57\u6587\u5316\u9057\u4ea7/\u535a\u7269\u9986\uff08Marttila\u3001Bhowmik\uff09\u3001VR \u5177\u8eab\uff08Landau\uff09\u3001\u7535\u5f71/\u4f5c\u66f2/\u670d\u88c5\u7b49\u521b\u4f5c\u5b9e\u8df5\u578b\u7814\u7a76\uff08Afdile\u3001Mancianti\u3001Manninen\uff09\u3001\u53c2\u4e0e\u5f0f\u4e0e\u5f00\u653e\u8bbe\u8ba1\u3002\u65b9\u6cd5\u4ee5\u5b9e\u8df5\u578b/\u827a\u672f\u7814\u7a76\uff08practice-based, artistic research\uff09\u548c\u8bbe\u8ba1\u7814\u7a76\u4e3a\u4e3b\uff0c\u8f85\u4ee5\u5c11\u91cf\u6280\u672f\u578b\uff08\u6d3b\u52a8\u8bc6\u522b\uff09\u3002\", \"design_background_ok_zh\": \"\u975e\u5e38\u53cb\u597d\uff1a\u591a\u540d\u5b66\u751f\u4e3a\u7535\u5f71\u4eba\u3001\u4f5c\u66f2\u5bb6\u3001\u670d\u88c5\u8bbe\u8ba1\u5e08\u3001\u5a92\u4f53\u827a\u672f\u5bb6\uff0c\u4ee5\u4f5c\u54c1+\u8bba\u6587\u96c6\u5f62\u5f0f\u6bd5\u4e1a\uff0cAalto ARTS \u662f\u827a\u672f\u535a\u58eb\uff08Doctor of Arts\uff09\u4f53\u7cfb\u3002\", \"chinese_students_zh\": \"Ningfeng Zhang 2026 \u5e74\u4ee5\u4e2d\u56fd\u7f51\u7edc\u8ff7\u56e0\u4e3a\u9898\u6bd5\u4e1a\uff0c\u59d3\u540d\u4e0e\u9898\u76ee\u5f3a\u70c8\u63d0\u793a\u4e3a\u4e2d\u56fd\u5b66\u751f\uff08\u6765\u6e90\u672a\u660e\u793a\u56fd\u7c4d/CSC\uff09\uff1bD\u00edaz \u4e0e\u6e56\u5357\u5927\u5b66\u7b49\u4e2d\u56fd\u9662\u6821\u6709\u5de5\u4f5c\u574a\u5408\u4f5c\u3002CSC \u8bb0\u5f55\u672a\u67e5\u5230\u3002\", \"implication_zh\": \"\u4e0e\u7528\u6237\u65b9\u5411\u9ad8\u5ea6\u5951\u5408\uff08\u6570\u5b57\u6587\u5316\u9057\u4ea7+VR/\u624b\u52bf\u4ea4\u4e92+\u535a\u7269\u9986\uff0cVrouw Maria \u624b\u52bf VR \u9879\u76ee\uff09\u3002\u53ef\u5f15\u7528 Landau \u7684 VR \u865a\u62df\u5177\u8eab\u3001Marttila \u7684\u6587\u5316\u516c\u5730\u548c Pop-up VR Museum \u9879\u76ee\u4f5c\u4e3a\u5207\u5165\uff0c\u5f3a\u8c03\u5b9e\u8df5\u578b\u7814\u7a76\u548c\u4f5c\u54c1\u96c6\u3002\u98ce\u9669\uff1aAalto \u827a\u672f\u535a\u58eb\u901a\u5e38\u65e0\u85aa\u9700\u81ea\u7b79\uff08CSC \u9002\u914d\uff09\uff0c\u4e14 D\u00edaz \u8d44\u6df1\u3001\u53ef\u80fd\u4e34\u8fd1\u9000\u4f11\uff0c\u9700\u786e\u8ba4 2027 \u4ecd\u53ef\u4f5c\u4e3a supervising professor\u3002\", \"sources\": [\"https://research.aalto.fi/en/persons/lily-diaz-kommonen/supervised/\", \"https://aaltodoc.aalto.fi/items/a85350fe-76bd-45d8-acff-c7f6a94c40bd\", \"https://interaccio.diba.cat/sites/interaccio.diba.cat/files/marttila.pdf\"], \"searched\": [\"Aalto research portal Supervised Work\uff0821 \u7bc7\uff09\", \"aaltodoc \u8bba\u6587\u5e93\", \"web \u641c\u7d22 supervising professor\"]}, \"title_zh\": \"\u65b0\u5a92\u4f53\u6559\u6388\uff1b\u8868\u5f81\u7cfb\u7edf\u7814\u7a76\u7ec4\u8d1f\u8d23\u4eba\uff1bMedia Lab \u535a\u58eb\u9879\u76ee\u534f\u8c03\u4eba\", \"unit_zh\": \"\u827a\u672f\u4e0e\u5a92\u4f53\u7cfb\uff0c\u827a\u672f\u3001\u8bbe\u8ba1\u4e0e\u5efa\u7b51\u5b66\u9662\uff08Aalto ARTS\uff09\", \"email_hook_zh\": \"\u60a8\u7684 Vrouw Maria \u88c5\u7f6e\u4ee5\u53ca\u4e3a\u8d6b\u5c14\u8f9b\u57fa\u8bbe\u8ba1\u535a\u7269\u9986\u6253\u9020\u7684\u5feb\u95ea VR \u535a\u7269\u9986\uff08Pop-up VR Museum\uff09\uff0c\u6b63\u662f\u6211\u5e0c\u671b\u4ee5\u624b\u52bf\u9a71\u52a8\u7684\u4e2d\u56fd\u9057\u4ea7\u5bf9\u8c61\u6765\u5f00\u5c55\u7684\u90a3\u79cd\u5b9e\u8df5\u578b\u9057\u4ea7\u7814\u7a76\u3002\", \"csc_status_zh\": \"\u672a\u627e\u5230\"}, {\"name\": \"Areti Galani\", \"school_en\": \"Newcastle University \u2013 Faculty of Humanities & Social Sciences\", \"school_zh\": \"\u7ebd\u5361\u65af\u5c14\u5927\u5b66\uff08\u4eba\u6587\u793e\u79d1\u5b66\u9662\uff09\", \"country\": \"\", \"title\": \"Professor of Digital Heritage Practices; Deputy Head of School of Arts and Cultures\", \"unit\": \"Media, Culture, Heritage, School of Arts and Cultures, Newcastle University\", \"homepage\": \"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"email\": null, \"relevance\": 9, \"claim\": \"Galani \u662f\u7ebd\u5361\u65af\u5c14\u6570\u5b57\u9057\u4ea7\u5b9e\u8df5\u6559\u6388\uff0c\u957f\u671f\u7528 research-through-design \u5728\u535a\u7269\u9986\u4e2d\u8bbe\u8ba1\u5e76\u8bc4\u4f30\u4ea4\u4e92\u88c5\u7f6e\u4e0e AR \u4f53\u9a8c\uff0c\u4e14\u4e3b\u5bfc Digital Media PhD \u4e2d'\u535a\u7269\u9986\u3001\u753b\u5eca\u4e0e\u9057\u4ea7\u4e2d\u7684\u6570\u5b57\u5a92\u4f53'\u65b9\u5411\uff0c\u662f\u8be5\u6821 AHRC DLA \u7ebf\u4e0a\u6700\u5bf9\u53e3\u7684\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"evidence_papers\": [{\"title\": \"Configuring slow technology through social and embodied interaction: Making time for reflection in augmented reality museum experiences with young visitors\", \"year\": 2019, \"venue\": \"Routledge (book chapter)\", \"url\": \"https://doi.org/10.4324/9780429506765-23\", \"link_to_user\": \"AR \u535a\u7269\u9986\u4e2d\u7684\u793e\u4f1a\u4e0e\u5177\u8eab\u4ea4\u4e92 \u2192 Stone Reveal \u7684'\u6162'\u4eea\u5f0f\u5316\u624b\u52bf\", \"title_zh\": \"\u901a\u8fc7\u793e\u4f1a\u6027\u4e0e\u5177\u8eab\u4ea4\u4e92\u914d\u7f6e\u6162\u6280\u672f\uff1a\u5728\u9762\u5411\u9752\u5c11\u5e74\u89c2\u4f17\u7684\u589e\u5f3a\u73b0\u5b9e\u535a\u7269\u9986\u4f53\u9a8c\u4e2d\u4e3a\u53cd\u601d\u7559\u51fa\u65f6\u95f4\"}, {\"title\": \"Designing for intersubjectivity and dialogicality in museum interactive installations about migration\", \"year\": 2020, \"venue\": \"Digital Creativity\", \"url\": \"https://doi.org/10.1080/14626268.2020.1848873\", \"link_to_user\": \"\u535a\u7269\u9986\u4ea4\u4e92\u88c5\u7f6e\u8bbe\u8ba1 \u2192 \u6587\u5316\u6839\u690d\u7684\u4ea4\u4e92\u6620\u5c04\", \"title_zh\": \"\u5728\u5173\u4e8e\u79fb\u6c11\u7684\u535a\u7269\u9986\u4e92\u52a8\u88c5\u7f6e\u4e2d\u4e3a\u4e3b\u4f53\u95f4\u6027\u4e0e\u5bf9\u8bdd\u6027\u800c\u8bbe\u8ba1\"}, {\"title\": \"Recasting witnessing in museums: digital interactive displays for dialogic remembering\", \"year\": 2020, \"venue\": \"International Journal of Heritage Studies\", \"url\": \"https://doi.org/10.1080/13527258.2020.1795909\", \"link_to_user\": \"\u6570\u5b57\u4e92\u52a8\u5c55\u9648\u4e0e\u8bb0\u5fc6 \u2192 \u60c5\u611f\u6295\u5165\u4e0e\u6587\u5316\u5b66\u4e60\", \"title_zh\": \"\u91cd\u5851\u535a\u7269\u9986\u4e2d\u7684\u89c1\u8bc1\uff1a\u7528\u4e8e\u5bf9\u8bdd\u5f0f\u8bb0\u5fc6\u7684\u6570\u5b57\u4ea4\u4e92\u5c55\u9648\"}], \"evidence_projects_funding\": \"\u4e2a\u4eba\u7ad9\u4e0e\u4e3b\u9875\uff1aRock Art on Mobile Phones (RAMP)\u3001The Borrowers AR\u3001Sit with Me\uff08Discovery Museum \u88c5\u7f6e\uff09\uff1bEuropean Heritage, Dialogue and Digital Practices\uff08OA \u4e13\u8457\uff0c\u5408\u7f16\uff09\uff1b\u4e0e Great North Museum: Hancock \u5408\u4f5c\uff1bRoutledge \u6570\u5b57 GLAM \u5b9e\u8df5\u56fd\u9645\u624b\u518c\u5408\u7f16\u3002\", \"fit_to_user\": \"\u5979\u7684\u7814\u7a76\u51e0\u4e4e\u5c31\u662f\u7528\u6237\u7684\u7814\u7a76\u95ee\u9898\uff1a\u5728\u771f\u5b9e\u535a\u7269\u9986\u91cc\u8bbe\u8ba1\u5177\u8eab/AR \u4ea4\u4e92\u5e76\u505a\u53cd\u601d\u6027\u8bc4\u4f30\uff1b\u65b9\u6cd5\uff08\u7814\u7a76\u6027\u8bbe\u8ba1 + \u5b9e\u5730\u8bc4\u4f30\uff09\u4e0e\u7528\u6237 RQ2/RQ3 \u5b8c\u5168\u5bf9\u9f50\u3002\", \"counterargument_risk\": \"\u4efb\u526f\u9662\u957f\uff0c\u884c\u653f\u8d1f\u62c5\u91cd\uff1b\u7814\u7a76\u504f\u793e\u4f1a\u6027/\u5bf9\u8bdd\u6027\u4e0e\u8d28\u6027\u65b9\u6cd5\uff0c\u5bf9\u7167\u5b9e\u9a8c\u4e0e\u7167\u660e\u6280\u672f\u652f\u6301\u8f83\u5f31\uff1b\u4e3b\u9875\u672a\u516c\u5f00\u90ae\u7bb1\uff08\u7f51\u9875\u53ef\u80fd\u811a\u672c\u9690\u85cf\uff09\u3002\", \"email_hook\": \"Your work on slow technology and embodied interaction in AR museum experiences, and on interactive installations such as Sit with Me, is the closest research I know to what my gesture-driven heritage prototypes are trying to do.\", \"sources\": [\"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"https://aretigalani.com/\", \"https://orcid.org/0000-0001-8045-6662\", \"https://www.ncl.ac.uk/postgraduate/degrees/8834f-43/\"], \"verified\": true, \"csc_note\": \"AHRC Doctoral Landscape Awards 2027 \u5165\u5b66\uff08HaSS \u5b66\u9662\uff0c2026 \u5e74\u6bcf\u5e74 5 \u4e2a\u540d\u989d\uff09\uff1bOpen Lab \u5c5e\u8ba1\u7b97\u673a\u5b66\u9662\uff0c\u4e0d\u5728 DLA \u8303\u56f4\uff1b\u7ebd\u5361\u65af\u5c14 CSC \u72b6\u6001\u672a\u63d0\u4f9b\u3002\", \"matched_keywords\": [\"museum digital cultural heritage\", \"embodied interaction\", \"AR\", \"research through design\"], \"csc_status\": \"unknown\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": null, \"subject\": \"PhD enquiry (AHRC DLA 2027): gesture-driven, embodied interaction in museums\", \"body\": \"Dear Professor Galani,\\n\\nYour work on slow technology and embodied interaction in AR museum experiences, and installations such as Sit with Me at the Discovery Museum, is the closest research I know to what my gesture-driven heritage prototypes are trying to do. I would like to apply for a PhD in Media, Culture, Heritage.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales) and did light-distribution analysis for Abu Dhabi's Zayed Airport project, and at LEEDARSON led user research for smart-lighting lines selling over US$30M. So I know how to make responsive light work in galleries and test it with users; my office offers students for co-design.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures as Three.js GPU particle clouds with in-browser MediaPipe hand tracking; visitors brush away the \\\"dust\\\" with a fingertip and join palms to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction and responsive, narrative lighting shape visitors' presence, reflection, emotional engagement and cultural learning around heritage objects, developing culturally grounded gesture-light mappings through co-design and evaluating them in the gallery and against static displays.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI plan to apply for an AHRC Doctoral Landscape Award through the Faculty of Humanities and Social Sciences for 2027 entry. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u6700\u5bf9\u53e3\uff089/10\uff09\u3002\u5207\u5165\u70b9\uff1aAR \u535a\u7269\u9986\u4e2d\u7684'\u6162\u6280\u672f'\u4e0e\u5177\u8eab\u4ea4\u4e92 + Sit with Me \u88c5\u7f6e\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u4e3b\u9875\u672a\u89c1\u516c\u5f00\u90ae\u7bb1\uff08Google Scholar \u663e\u793a ncl.ac.uk \u5df2\u9a8c\u8bc1\uff09\uff0c\u53ef\u901a\u8fc7 SACS PGR \u529e\u516c\u5ba4\uff08SACS.PGR.Admin@newcastle.ac.uk\uff09\u8be2\u95ee\u6216\u67e5\u5b66\u6821\u901a\u8baf\u5f55\uff1bDLA \u56fd\u9645\u751f\u540d\u989d\u4e0e\u622a\u6b62\u65e5\u671f\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff08AHRC DLA 2027\uff09\uff1a\u535a\u7269\u9986\u4e2d\u7684\u624b\u52bf\u9a71\u52a8\u5177\u8eab\u4ea4\u4e92\", \"body_zh\": \"\u5c0a\u656c\u7684 Galani \u6559\u6388\uff1a\\n\\n\u60a8\u5728 AR \u535a\u7269\u9986\u4f53\u9a8c\u4e2d\u5173\u4e8e\u6162\u6280\u672f\u4e0e\u5177\u8eab\u4ea4\u4e92\u7684\u7814\u7a76\uff0c\u4ee5\u53ca Discovery Museum\uff08\u63a2\u7d22\u535a\u7269\u9986\uff09\u4e2d\u7684 Sit with Me\uff08\u300a\u4e0e\u6211\u540c\u5750\u300b\uff09\u7b49\u88c5\u7f6e\uff0c\u662f\u6211\u6240\u77e5\u4e0e\u6211\u7684\u624b\u52bf\u9a71\u52a8\u9057\u4ea7\u539f\u578b\u60f3\u505a\u7684\u4e8b\u60c5\u6700\u63a5\u8fd1\u7684\u7814\u7a76\u3002\u6211\u5e0c\u671b\u7533\u8bf7\u5a92\u4f53\u3001\u6587\u5316\u4e0e\u9057\u4ea7\uff08Media, Culture, Heritage\uff09\u65b9\u5411\u7684\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u62c5\u4efb\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u56e0\u6b64\uff0c\u6211\u61c2\u5f97\u5982\u4f55\u8ba9\u54cd\u5e94\u5f0f\u706f\u5149\u5728\u5c55\u5385\u4e2d\u843d\u5730\u5e76\u4e0e\u7528\u6237\u4e00\u8d77\u6d4b\u8bd5\uff1b\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u4e3a\u5171\u540c\u8bbe\u8ba1\u63d0\u4f9b\u5b66\u751f\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u505a\u6210 Three.js GPU \u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u5185\u8fdb\u884c MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff1b\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u624b\u5408\u5341\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u5219\u4ee5\u540c\u6837\u7684\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u624b\u52bf\u9a71\u52a8\u7684\u4ea4\u4e92\u4e0e\u54cd\u5e94\u5f0f\u53d9\u4e8b\u7167\u660e\u5982\u4f55\u5f71\u54cd\u89c2\u4f17\u56f4\u7ed5\u9057\u4ea7\u6587\u7269\u7684\u4e34\u573a\u611f\u3001\u53cd\u601d\u3001\u60c5\u611f\u6295\u5165\u548c\u6587\u5316\u5b66\u4e60\uff1a\u901a\u8fc7\u5171\u540c\u8bbe\u8ba1\u5f62\u6210\u690d\u6839\u4e8e\u6587\u5316\u7684\u624b\u52bf\u2013\u5149\u6620\u5c04\uff0c\u5e76\u5728\u5c55\u5385\u4e2d\u52a0\u4ee5\u8bc4\u4f30\u3001\u4e0e\u9759\u6001\u5c55\u793a\u8fdb\u884c\u6bd4\u8f83\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u662f\u4e24\u7bc7 MR \u8bba\u6587\u7684\u5408\u8457\u8005\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5c3d\u65e9\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u6211\u8ba1\u5212\u901a\u8fc7\u4eba\u6587\u4e0e\u793e\u4f1a\u79d1\u5b66\u5b66\u9662\u7533\u8bf7 2027 \u5e74\u5165\u5b66\u7684 AHRC \u535a\u58eb\u5956\u5b66\u91d1\uff08Doctoral Landscape Award\uff09\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u5bc4\u4e0a\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Dan Foster-Smith\", \"status\": \"current\", \"start_year\": null, \"thesis_title\": \"Augmenting Creativity: exploring AI to assist in creative ideation processes\", \"topic_zh\": \"\u7528AI\u8f85\u52a9\u521b\u610f\u6784\u601d\", \"url\": \"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"note\": \"Galani \u4e0e Schofield \u4e2a\u4eba\u9875\u5747\u5217\u4e3a\u5176\u5728\u8bfb\u535a\u58eb\"}, {\"name\": \"Gobi Gao\", \"status\": \"current\", \"start_year\": null, \"thesis_title\": \"PhD (topic not stated on Galani profile)\", \"topic_zh\": \"\u5728\u8bfb\uff08\u8bfe\u9898\u672a\u5217\uff09\", \"url\": \"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Samantha Vaughn\", \"status\": \"alumni\", \"graduation_year\": 2025, \"thesis_title\": \"Negotiating post-1989 identities: Foreign visitor encounters in museums of Communism\", \"topic_zh\": \"1989\u540e\u8eab\u4efd\u534f\u5546\uff1a\u5916\u56fd\u6e38\u5ba2\u5728\u5171\u4ea7\u4e3b\u4e49\u535a\u7269\u9986\u4e2d\u7684\u4f53\u9a8c\", \"url\": \"https://theses.ncl.ac.uk/jspui/handle/10443/6633\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"David Farrell-Banks\", \"status\": \"alumni\", \"graduation_year\": 2021, \"thesis_title\": \"Moving Moments: Uses of European Pasts in Heritage and Political Discourse\", \"topic_zh\": \"\u201c\u79fb\u52a8\u7684\u65f6\u523b\u201d\uff1a\u9057\u4ea7\u4e0e\u653f\u6cbb\u8bdd\u8bed\u4e2d\u5bf9\u6b27\u6d32\u8fc7\u53bb\u7684\u4f7f\u7528\", \"url\": \"https://theses.ncl.ac.uk/jspui/handle/10443/5464\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Bethany Rex\", \"status\": \"alumni\", \"graduation_year\": 2018, \"thesis_title\": \"Local authority museums after the cuts: a study of other-than-public forms of management\", \"topic_zh\": \"\u524a\u51cf\u7ecf\u8d39\u540e\u7684\u5730\u65b9\u653f\u5e9c\u535a\u7269\u9986\uff1a\u975e\u516c\u5171\u7ba1\u7406\u5f62\u5f0f\u7814\u7a76\", \"url\": \"https://theses.ncl.ac.uk/jspui/bitstream/10443/4118/1/Rex%20B.%202018.pdf\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u5bfc\u5e08 Andrew Newman & Areti Galani\uff08\u81f4\u8c22\uff09\", \"note_zh\": \"\u5bfc\u5e08 Andrew Newman \u4e0e Areti Galani\uff08\u81f4\u8c22\uff09\"}, {\"name\": \"Gabriella (Gabi) Arrigoni\", \"status\": \"alumni\", \"graduation_year\": 2017, \"thesis_title\": \"Artistic prototypes: from laboratory practices to curatorial strategies\", \"topic_zh\": \"\u827a\u672f\u539f\u578b\uff1a\u4ece\u5b9e\u9a8c\u5ba4\u5b9e\u8df5\u5230\u7b56\u5c55\u7b56\u7565\", \"url\": \"https://theses.ncl.ac.uk/jspui/handle/10443/3572\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Katherine (Kat) Lloyd\", \"status\": \"alumni\", \"graduation_year\": 2014, \"thesis_title\": \"Narratives of belonging and exclusion: the negotiation of heritage and place in young people's conceptualisations of national identity in Scotland\", \"topic_zh\": \"\u82cf\u683c\u5170\u9752\u5e74\u56fd\u5bb6\u8ba4\u540c\u4e2d\u7684\u9057\u4ea7\u4e0e\u5730\u65b9\u534f\u5546\", \"url\": \"https://theses.ncl.ac.uk/jspui/handle/10443/2550\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Danae Peguero Bueno / Daisy-Alys Vaughan / Brian Moss / Rebecca Farley / Bronwen Colquhoun / Anna Goulding / Rachel Clarke\", \"status\": \"alumni\", \"graduation_year\": null, \"thesis_title\": \"Graduated PhD students listed on Galani profile (titles not retrieved)\", \"topic_zh\": \"Galani \u4e2a\u4eba\u9875\u5217\u51fa\u7684\u5176\u4ed6\u6bd5\u4e1a\u751f\uff08\u9898\u76ee\u672a\u68c0\u7d22\uff09\", \"url\": \"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"\u5728\u8bfb2 / \u5df2\u6bd5\u4e1a13\uff08\u4e2a\u4eba\u9875\u5217\u51fa\uff09\uff0c\u8fd110\u5e74\u7ea68\", \"student_pattern_zh\": \"\u535a\u7269\u9986\u4e0e\u9057\u4ea7\u7814\u7a76\uff1a\u6570\u5b57/\u5bf9\u8bdd\u5f0f\u9057\u4ea7\u5b9e\u8df5\u3001\u6e38\u5ba2\u7814\u7a76\u3001\u535a\u7269\u9986\u7ba1\u7406\u3001\u8bb0\u5fc6\u4e0e\u653f\u6cbb\u3001\u827a\u672f\u539f\u578b\u7b56\u5c55\uff1b\u4eba\u672c\u65b9\u6cd5\uff08\u6587\u5316\u63a2\u9488\u3001\u89d2\u8272\u626e\u6f14\u3001\u62fc\u8d34\u3001\u8eab\u4f53\u5730\u56fe\u3001\u6c11\u65cf\u5fd7\uff09\uff0c\u5e76\u660e\u786e\u6b22\u8fce\u521b\u610f\u5b9e\u8df5\u578b\uff08practice-based\uff09\u535a\u58eb\u3002\", \"design_background_ok_zh\": \"\u975e\u5e38\u53cb\u597d\uff1aGalani \u672c\u4eba\u4e3a\u8ba1\u7b97\u79d1\u5b66\u535a\u58eb+\u535a\u7269\u9986\u5b66\uff0c\u91c7\u7528\u7814\u7a76\u578b\u8bbe\u8ba1\uff08RtD\uff09\uff1b\u4e2a\u4eba\u9875\u5199\u660e\u63a5\u6536\u201c\u5305\u62ec\u521b\u610f\u5b9e\u8df5\u578b\u7814\u7a76\u201d\u7684\u535a\u58eb\uff0c\u65b9\u5411\u542b\u201c\u535a\u7269\u9986\u4e2d\u79fb\u52a8/\u666e\u9002\u6280\u672f\u7684\u8bbe\u8ba1\u4e0e\u4f7f\u7528\u201d\u3002\", \"chinese_students_zh\": \"\u5728\u8bfb Gobi Gao \u4e3a\u4e2d\u56fd\u59d3\u540d\u5b66\u751f\uff08\u56fd\u7c4d/\u8d44\u52a9\u672a\u6ce8\u660e\uff09\u3002\", \"implication_zh\": \"\u9ad8\u5ea6\u5951\u5408\uff1a\u53ef\u5f15\u7528 Arrigoni\u300a\u827a\u672f\u539f\u578b\uff1a\u4ece\u5b9e\u9a8c\u5ba4\u5b9e\u8df5\u5230\u7b56\u5c55\u7b56\u7565\u300b\u4e0e\u5176\u201c\u535a\u7269\u9986\u793e\u4ea4\u4f53\u9a8c/\u6e38\u5ba2\u7814\u7a76\u201d\u65b9\u5411\uff0c\u63d0\u51fa\u201c\u624b\u52bf+\u706f\u5149\u7684\u535a\u7269\u9986\u793e\u4ea4\u4e92\u52a8\u5c55\u9879\uff08RtD\uff09\u201d\u3002Newcastle \u6709 Culture Lab \u4e0e Open Lab \u652f\u6491\u539f\u578b\u3002\u98ce\u9669\uff1a\u82f1\u56fd\u56fd\u9645\u751f\u5b66\u8d39\u9ad8\uff0c\u9700 CSC \u6216 Northern Bridge \u5956\u5b66\u91d1\uff1b\u9700\u5199\u6e05\u4eba\u6587\u5b66\u79d1\u7814\u7a76\u95ee\u9898\u3002\", \"sources\": [\"https://www.ncl.ac.uk/sacs/people/profile/aretigalani.html\", \"https://theses.ncl.ac.uk/jspui/handle/10443/6633\", \"https://theses.ncl.ac.uk/jspui/handle/10443/5464\", \"https://theses.ncl.ac.uk/jspui/bitstream/10443/4118/1/Rex%20B.%202018.pdf\", \"https://theses.ncl.ac.uk/jspui/handle/10443/3572\", \"https://theses.ncl.ac.uk/jspui/handle/10443/2550\"], \"searched\": [\"Newcastle \u4e2a\u4eba\u9875 Postgraduate Research Supervision\", \"Newcastle eTheses\uff08\u6309\u5b66\u751f\u59d3\u540d\u68c0\u7d22\uff09\", \"\u8bba\u6587\u81f4\u8c22\", \"aretigalani.com\"]}, \"title_zh\": \"\u6570\u5b57\u9057\u4ea7\u5b9e\u8df5\u6559\u6388\uff1b\u827a\u672f\u4e0e\u6587\u5316\u5b66\u9662\u526f\u9662\u957f\", \"unit_zh\": \"\u5a92\u4f53\u3001\u6587\u5316\u3001\u9057\u4ea7\u65b9\u5411\uff0c\u7ebd\u5361\u65af\u5c14\u5927\u5b66\u827a\u672f\u4e0e\u6587\u5316\u5b66\u9662\", \"evidence_projects_funding_zh\": \"\u4e2a\u4eba\u7ad9\u4e0e\u4e3b\u9875\uff1a\u624b\u673a\u4e0a\u7684\u5ca9\u753b\uff08Rock Art on Mobile Phones\uff0cRAMP\uff09\u3001\u501f\u4e1c\u897f\u7684\u5c0f\u4eba AR\uff08The Borrowers AR\uff09\u3001\u4e0e\u6211\u540c\u5750\uff08Sit with Me\uff0cDiscovery Museum \u88c5\u7f6e\uff09\uff1b\u300a\u6b27\u6d32\u9057\u4ea7\u3001\u5bf9\u8bdd\u4e0e\u6570\u5b57\u5b9e\u8df5\u300b\uff08European Heritage, Dialogue and Digital Practices\uff0c\u5f00\u653e\u83b7\u53d6\u4e13\u8457\uff0c\u5408\u7f16\uff09\uff1b\u4e0e\u6c49\u8003\u514b\u5927\u5317\u65b9\u535a\u7269\u9986\uff08Great North Museum: Hancock\uff09\u5408\u4f5c\uff1bRoutledge\u300a\u6570\u5b57 GLAM \u5b9e\u8df5\u56fd\u9645\u624b\u518c\u300b\u5408\u7f16\u3002\", \"email_hook_zh\": \"\u60a8\u5728\u589e\u5f3a\u73b0\u5b9e\u535a\u7269\u9986\u4f53\u9a8c\u4e2d\u7684\u6162\u6280\u672f\u4e0e\u5177\u8eab\u4ea4\u4e92\u65b9\u9762\u7684\u7814\u7a76\uff0c\u4ee5\u53ca\u300a\u4e0e\u6211\u540c\u5750\u300b\uff08Sit with Me\uff09\u7b49\u4e92\u52a8\u88c5\u7f6e\uff0c\u662f\u6211\u6240\u77e5\u4e0e\u6211\u624b\u52bf\u9a71\u52a8\u9057\u4ea7\u539f\u578b\u7684\u76ee\u6807\u6700\u4e3a\u63a5\u8fd1\u7684\u7814\u7a76\u3002\", \"csc_status_zh\": \"\u672a\u77e5\"}, {\"name\": \"Sylvia Pont\", \"school_en\": \"Delft University of Technology (TU Delft)\", \"school_zh\": \"\u4ee3\u5c14\u592b\u7279\u7406\u5de5\u5927\u5b66\", \"country\": \"Netherlands\", \"title\": \"\", \"unit\": \"Perceptual Intelligence Lab (\u03c0-lab), Faculty of Industrial Design Engineering (IDE)\", \"homepage\": \"https://www.tudelft.nl/en/ide/about-ide/people/pont-sc\", \"email\": \"S.C.Pont@tudelft.nl\", \"relevance\": 8, \"claim\": \"\u03c0-lab offers the perceptual-science rigour that would turn the user's intuition about 'narrative lighting' into measurable claims about how light shapes perception of heritage objects.\", \"evidence_homepage\": \"Professor of Perceptual Intelligence, head of \u03c0-lab and section; works on perception and design of multisensory experiences and products, light, materials and spaces. Involved in research project 'Explora \u2014 Perception of materials, objects and spaces through active EXPLORAtion'.\", \"evidence_papers\": [\"Lighting Materials and Materializing Light (LS 2024) \u2192 museum lighting of bronze surfaces\", \"Varying illumination colors transform still images (i-Perception 2026) \u2192 dynamic light on murals\", \"Pseudo-haptic photograph interaction (ToH 2025) \u2192 interaction-mediated perception\"], \"evidence_projects_funding\": \"Homepage lists project Explora (active exploration of materials/objects/spaces). No open PhD call verified.\", \"fit_to_user\": \"Lighting-product background (light distribution analysis, DIALux) + gesture prototypes \u2192 'active exploration' of heritage objects under interactive light matches Explora's theme.\", \"counterargument_risk\": \"Perception-science lab: expects psychophysics/experimental rigour; CSC route at Delft uncertain and underfunded; competition high.\", \"email_hook\": \"Connect 'Explora \u2014 active exploration of materials and objects' with a study where visitors' hand gestures steer light over a bronze vessel, measuring perceived material/meaning.\", \"sources\": [\"https://doi.org/10.1109/ls2463127.2024.10881255\"], \"verified\": true, \"csc_note\": \"TU Delft is on the user's 2016 list, but reported in 2023 as 'increasingly reluctant' to admit CSC PhDs (https://nltimes.nl/2023/05/02/dutch-universities-reluctant-accept-chinese-scholarship-phd-students) and gives no top-up to scholarship PhDs (https://ukrant.nl/magazine/international-scholarship-phds-have-to-take-on-extra-jobs-now-that-theyre-getting-less-money-than-expected/?lang=en). Funded PhD vacancies: none verified.\", \"matched_keywords\": [\"narrative/storytelling lighting\", \"HCI\", \"digital media & interaction design\", \"research-through-design\"], \"csc_status\": \"paused_or_stopped\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"S.C.Pont@tudelft.nl\", \"subject\": \"PhD enquiry: interactive light and the perception of heritage objects (\u03c0-lab)\", \"body\": \"Dear Professor Pont,\\n\\nYour recent papers \\\"To appear in a new light: Varying illumination colors induce dynamic transformations of perceptual qualities in still images\\\" and \\\"Interactions of Light with Materials \u2013 Lighting Materials and Materializing Light\\\" address something I could only work on intuitively as a lighting product manager: how changing light changes what an object appears to be.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales) and did light-distribution analysis for Abu Dhabi's Zayed Airport project, and at LEEDARSON led user research (Amazon data, DEMATEL) for smart-lighting lines selling over US$30M. So I know light from the engineering and user side; my office offers students and heritage material for studies. My current prototypes put heritage objects under visitors' hands: in Bronze Heritage Gesture Interaction (https://cooleli.github.io/Portfolio-page/Bronze%20Heritage%20Gesture%20Interaction%20project/) five Chinese bronzes become GPU particle clouds that visitors melt, rotate and reassemble with markerless MediaPipe hand tracking.\\n\\nFor a PhD I would like to make this rigorous. In the spirit of the Explora project's active exploration, visitors' hand gestures would steer real, programmable light over a bronze surface or a mural reproduction. I would then measure how gesture-driven, narrative light changes perceived material qualities, attention and cultural interpretation compared with static museum lighting. The aim: design principles grounded in perception data.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I offer working prototypes, a granted MR invention patent and a practice-based approach I would turn into peer-reviewed studies early on.\\n\\nOn funding: I understand TU Delft has had no institutional CSC agreement since 2018 and offers no top-up, although some faculties still admit individually funded CSC candidates. Would you be open to supervising this topic, either through a funded vacancy or, if IDE allows it, as an individual CSC-funded candidate (application March 2027)?\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aPont \u7814\u7a76\u5149\u5982\u4f55\u6539\u53d8\u6750\u8d28/\u56fe\u50cf\u611f\u77e5\uff0c\u4f60\u7684\u7167\u660e\u4ea7\u54c1\u7ecf\u9a8c+\u9752\u94dc\u624b\u52bf\u539f\u578b\u6b63\u597d\u80fd\u53d8\u6210\u53ef\u6d4b\u91cf\u7684\u611f\u77e5\u5b9e\u9a8c\uff1bExplora \u9879\u76ee\u5bf9\u5e94\u201c\u4e3b\u52a8\u63a2\u7d22\u201d\u3002\u53d1\u9001\u524d\u6838\u5b9e\uff1aTU Delft \u81ea 2018 \u5e74\u65e0 CSC \u5408\u4f5c\u534f\u8bae\u3001\u4ec5\u4e2a\u522b\u9662\u7cfb\u63a5\u6536\u4e2a\u4eba\u6e20\u9053 CSC\uff0c\u786e\u8ba4 IDE \u662f\u5426\u63a5\u53d7\uff1b\u03c0-lab \u6709\u65e0\u7a7a\u7f3a\uff1b\u628a\u201cpsychophysical\u201d\u8bf4\u6cd5\u786e\u8ba4\u5408\u9002\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff1a\u4ea4\u4e92\u5f0f\u5149\u4e0e\u9057\u4ea7\u6587\u7269\u7684\u611f\u77e5\uff08\u03c0-lab\uff09\", \"body_zh\": \"\u5c0a\u656c\u7684 Pont \u6559\u6388\uff1a\\n\\n\u60a8\u8fd1\u671f\u7684\u8bba\u6587 \\\"To appear in a new light: Varying illumination colors induce dynamic transformations of perceptual qualities in still images\\\"\uff08\u300a\u4ee5\u65b0\u7684\u5149\u5448\u73b0\uff1a\u53d8\u5316\u7684\u7167\u660e\u989c\u8272\u5f15\u53d1\u9759\u6001\u56fe\u50cf\u611f\u77e5\u7279\u8d28\u7684\u52a8\u6001\u8f6c\u53d8\u300b\uff09\u548c \\\"Interactions of Light with Materials \u2013 Lighting Materials and Materializing Light\\\"\uff08\u300a\u5149\u4e0e\u6750\u6599\u7684\u76f8\u4e92\u4f5c\u7528\u2014\u2014\u7167\u4eae\u6750\u6599\u4e0e\u7269\u5316\u5149\u300b\uff09\u63a2\u8ba8\u4e86\u6211\u4f5c\u4e3a\u7167\u660e\u4ea7\u54c1\u7ecf\u7406\u65f6\u53ea\u80fd\u51ed\u76f4\u89c9\u5904\u7406\u7684\u95ee\u9898\uff1a\u53d8\u5316\u7684\u5149\u5982\u4f55\u6539\u53d8\u4e00\u4e2a\u7269\u4f53\u770b\u8d77\u6765\u662f\u4ec0\u4e48\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u62c5\u4efb\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u56e0\u6b64\uff0c\u6211\u4ece\u5de5\u7a0b\u548c\u7528\u6237\u4e24\u65b9\u9762\u4e86\u89e3\u5149\uff1b\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u4e3a\u7814\u7a76\u63d0\u4f9b\u5b66\u751f\u548c\u9057\u4ea7\u7d20\u6750\u3002\u6211\u76ee\u524d\u7684\u539f\u578b\u628a\u9057\u4ea7\u6587\u7269\u4ea4\u5230\u89c2\u4f17\u624b\u4e2d\uff1a\u5728 Bronze Heritage Gesture Interaction\uff08\u300a\u9752\u94dc\u9057\u4ea7\u624b\u52bf\u4ea4\u4e92\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Bronze%20Heritage%20Gesture%20Interaction%20project/\uff09\u4e2d\uff0c\u4e94\u4ef6\u4e2d\u56fd\u9752\u94dc\u5668\u53d8\u6210 GPU \u7c92\u5b50\u4e91\uff0c\u89c2\u4f17\u501f\u52a9\u65e0\u6807\u8bb0\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\u5bf9\u5176\u8fdb\u884c\u7194\u5316\u3001\u65cb\u8f6c\u548c\u91cd\u7ec4\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u8ba9\u8fd9\u9879\u5de5\u4f5c\u53d8\u5f97\u4e25\u8c28\u3002\u79c9\u627f Explora \u9879\u76ee\u201c\u4e3b\u52a8\u63a2\u7d22\u201d\u7684\u7406\u5ff5\uff0c\u89c2\u4f17\u7684\u624b\u52bf\u5c06\u64cd\u63a7\u7167\u5c04\u5728\u9752\u94dc\u5668\u8868\u9762\u6216\u58c1\u753b\u590d\u5236\u54c1\u4e0a\u7684\u771f\u5b9e\u53ef\u7f16\u7a0b\u5149\u3002\u968f\u540e\u6211\u5c06\u6d4b\u91cf\uff0c\u4e0e\u9759\u6001\u535a\u7269\u9986\u7167\u660e\u76f8\u6bd4\uff0c\u624b\u52bf\u9a71\u52a8\u7684\u53d9\u4e8b\u5149\u5982\u4f55\u6539\u53d8\u4eba\u4eec\u611f\u77e5\u5230\u7684\u6750\u8d28\u7279\u6027\u3001\u6ce8\u610f\u529b\u548c\u6587\u5316\u8be0\u91ca\u3002\u76ee\u6807\u662f\uff1a\u5f62\u6210\u4ee5\u611f\u77e5\u6570\u636e\u4e3a\u4f9d\u636e\u7684\u8bbe\u8ba1\u539f\u5219\u3002\\n\\n\u5766\u767d\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u5b66\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u662f\u4e24\u7bc7 MR \u8bba\u6587\u7684\u5408\u8457\u8005\uff09\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\uff0c\u6211\u4f1a\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u3002\\n\\n\u5173\u4e8e\u8d44\u52a9\uff1a\u6211\u4e86\u89e3\u5230\u4ee3\u5c14\u592b\u7279\u7406\u5de5\u5927\u5b66\uff08TU Delft\uff09\u81ea 2018 \u5e74\u8d77\u5df2\u6ca1\u6709\u4e0e\u56fd\u5bb6\u7559\u5b66\u57fa\u91d1\u59d4\uff08CSC\uff09\u7684\u6821\u7ea7\u534f\u8bae\uff0c\u4e5f\u4e0d\u63d0\u4f9b\u8865\u52a9\uff0c\u4f46\u90e8\u5206\u5b66\u9662\u4ecd\u63a5\u6536\u4e2a\u4eba\u83b7 CSC \u8d44\u52a9\u7684\u5019\u9009\u4eba\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\u2014\u2014\u65e0\u8bba\u662f\u901a\u8fc7\u5e26\u8d44\u52a9\u7684\u7a7a\u7f3a\u5c97\u4f4d\uff0c\u8fd8\u662f\uff08\u5982\u679c\u5de5\u4e1a\u8bbe\u8ba1\u5de5\u7a0b\u5b66\u9662 IDE \u5141\u8bb8\u7684\u8bdd\uff09\u4ee5\u4e2a\u4eba\u83b7 CSC \u8d44\u52a9\u5019\u9009\u4eba\u7684\u8eab\u4efd\uff082027 \u5e74 3 \u6708\u7533\u8bf7\uff09\uff1f\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Cehao Yu\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": 2023, \"thesis_title\": \"Light and spectra in the wild \u2013 Spectral structures of light fields: measurement, simulation and visualization\", \"topic_zh\": \"\u771f\u5b9e\u73af\u5883\u4e2d\u5149\u573a\u7684\u5149\u8c31\u7ed3\u6784\uff1a\u6d4b\u91cf\u3001\u4eff\u771f\u4e0e\u53ef\u89c6\u5316\uff08MSCA DyViTo\u7f51\u7edc\uff09\", \"url\": \"https://research.tudelft.nl/en/clippings/light-and-spectra-in-the-wild/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Willemijn Elkhuizen\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": 2019, \"thesis_title\": \"This is not a painting: Scanning and printing a painting's appearance\", \"topic_zh\": \"\u7ed8\u753b\u5916\u89c2\uff08\u5149\u6cfd\u3001\u7eb9\u7406\u3001\u8272\u5f69\uff09\u7684\u626b\u63cf\u4e0e3D\u6253\u5370\u590d\u5236\u2014\u2014\u6587\u5316\u9057\u4ea7\", \"url\": \"https://repository.tudelft.nl/record/uuid:e9476c36-066e-4c9c-a570-90eef0d319cb\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Tatiana Kartashova\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": 2018, \"thesis_title\": \"Structures of Physical and Visual Light Fields: Measurement, Comparison and Visualization\", \"topic_zh\": \"\u7269\u7406\u4e0e\u89c6\u89c9\u5149\u573a\u7ed3\u6784\uff08\u5149\u533a\u3001\u53ef\u89c6\u5316\u5de5\u5177\uff09\", \"url\": \"https://repository.tudelft.nl/record/uuid:fd7e7b74-5719-49f5-856a-a5ee3784c2ea\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Fan Zhang\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": null, \"thesis_title\": \"\uff08\u6750\u6599\u4e0e\u5149\u7167\u611f\u77e5\u7684\u4ea4\u4e92\uff1aMatMix/MixIM\u2014\u2014\u535a\u58eb\u8bba\u6587\u9898\u76ee\u672a\u6838\u5b9e\uff09\", \"topic_zh\": \"\u5178\u578b\u5149\u7167\u6a21\u5f0f\u4e0e\u6750\u8d28\u611f\u77e5\u7684\u6df7\u6dc6\", \"url\": \"https://repository.tudelft.nl/file/File_a235b25f-a434-46a0-b127-c41d875e5f3c\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Ling Xia\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": null, \"thesis_title\": \"\uff08\u771f\u5b9e\u573a\u666f\u89c6\u89c9\u5149\u573a\u4e0e\u6f2b\u5c04\u5ea6\u5ea6\u91cf\u2014\u2014\u535a\u58eb\u8bba\u6587\u9898\u76ee\u672a\u6838\u5b9e\uff0c\u03c0-lab\uff09\", \"topic_zh\": \"\u771f\u5b9e\u573a\u666f\u7684\u5149\u6269\u6563\u5ea6\u3001\u65b9\u5411\u4e0e\u5f3a\u5ea6\u7684\u611f\u77e5\", \"url\": \"https://pubmed.ncbi.nlm.nih.gov/28203350\", \"now\": \"\u6cb3\u6d77\u5927\u5b66\uff08\u5357\u4eac\uff09\uff08\u636e2017\u6458\u8981\u7f72\u540dHohai University - Nanjing\uff09\", \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"\u03c0-lab\u7ec4\u7ec7\u9875\u663e\u793a7\u7bc7TU Delft\u535a\u58eb\u8bba\u6587\uff08\u8fd1\u5e74\uff09\uff1bPont\u4efbpromotor\u7684\u8fd110\u5e74\u6bd5\u4e1a\u7ea65\u20138 / \u5728\u8bfb\u7ea63\u20135\uff08\u672a\u9010\u4e00\u5217\u51fa\uff09\", \"student_pattern_zh\": \"\u611f\u77e5\u5bfc\u5411\u7684\u7167\u660e\u4e0e\u6750\u6599\uff1a\u5149\u573a\u6d4b\u91cf\u4e0e\u53ef\u89c6\u5316\u3001\u5149\u8c31\u3001\u5149-\u6750\u8d28-\u5f62\u72b6\u4ea4\u4e92\u3001\u7ed8\u753b\u5916\u89c2\u590d\u5236\uff08\u9057\u4ea7\uff09\u3001\u6237\u5916\u7167\u660e\u7684\u751f\u6001/\u793e\u4f1a\u5149\u573a\u3002\u65b9\u6cd5\u4e3a\u5fc3\u7406\u7269\u7406\u5b9e\u9a8c+\u5149\u5b66\u6d4b\u91cf+\u53ef\u89c6\u5316\u5de5\u5177\uff0c\u5c5e\u611f\u77e5\u79d1\u5b66\u4e0e\u8bbe\u8ba1\u4ea4\u53c9\u7684\u5b9e\u9a8c\u578b\u3002\", \"design_background_ok_zh\": \"\u8f83\u53cb\u597d\uff1a\u5de5\u4e1a\u8bbe\u8ba1\u5de5\u7a0b\u5b66\u9662\uff08IDE\uff09\u80cc\u666f\u5b66\u751f\u5e38\u89c1\uff0c\u7855\u58eb\u6bd5\u8bbe\u4e2d\u6709\u2018biophilic light texture\u2019\u2018dynamic light textures\u2019\u7b49\u8bbe\u8ba1\u53d6\u5411\uff1b\u4f46\u535a\u58eb\u9700\u638c\u63e1\u5fc3\u7406\u7269\u7406\u5b9e\u9a8c\u4e0e\u5149\u5b66\u6d4b\u91cf\u3002\", \"chinese_students_zh\": \"\u6709\uff1aCehao Yu\u3001Fan Zhang\u3001Ling Xia\u4e3a\u4e2d\u6587\u540d\uff08Ling Xia\u73b0\u6cb3\u6d77\u5927\u5b66\uff09\uff1bCSC\u8d44\u52a9\u672a\u5728\u6765\u6e90\u4e2d\u660e\u786e\u5199\u51fa\u3002\", \"implication_zh\": \"\u2018\u53d9\u4e8b\u7167\u660e\u2019\u6700\u5bf9\u53e3\u7684\u611f\u77e5\u79d1\u5b66\u5bfc\u5e08\uff1a\u53ef\u63d0\u51fa\u2018\u975e\u9057\u5668\u7269/\u5c55\u9648\u7684\u5149\u573a\u8bbe\u8ba1\u4e0e\u89c2\u4f17\u611f\u77e5\u5b9e\u9a8c\u2019\uff0c\u5f15\u7528Elkhuizen\u7684\u7ed8\u753b\u5916\u89c2\u590d\u5236\u4e0eKartashova\u5149\u573a\u53ef\u89c6\u5316\u3002\u98ce\u9669\uff1a\u7814\u7a76\u9700\u4ee5\u611f\u77e5\u5b9e\u9a8c\u4e3a\u6838\u5fc3\uff0c\u7eaf\u827a\u672f\u53d9\u4e8b\u4e0d\u591f\uff1bTU Delft\u63a5\u53d7CSC\uff08\u9700\u53e6\u884c\u6838\u5b9e\u540d\u989d\uff09\u3002\", \"sources\": [\"https://research.tudelft.nl/en/organisations/perceptual-intelligence\", \"https://repository.tudelft.nl/record/uuid:fd7e7b74-5719-49f5-856a-a5ee3784c2ea\", \"https://repository.tudelft.nl/record/uuid:e9476c36-066e-4c9c-a570-90eef0d319cb\", \"https://research.tudelft.nl/en/clippings/light-and-spectra-in-the-wild/\"], \"searched\": [\"TU Delft Repository\uff08Promotor=Pont\uff09\", \"TU Delft Research Portal\u7ec4\u7ec7\u9875\", \"\u03c0-lab\u65b0\u95fb\", \"PubMed\u5408\u8457\", \"\u7855\u58eb\u6bd5\u8bbe\u62a5\u544a\"]}, \"country_zh\": \"\u8377\u5170\", \"unit_zh\": \"\u611f\u77e5\u667a\u80fd\u5b9e\u9a8c\u5ba4\uff08\u03c0-lab\uff09\uff0c\u5de5\u4e1a\u8bbe\u8ba1\u5de5\u7a0b\u5b66\u9662\uff08IDE\uff09\", \"claim_zh\": \"\u03c0-lab\u80fd\u63d0\u4f9b\u611f\u77e5\u79d1\u5b66\u7684\u4e25\u8c28\u6027\uff0c\u5c06\u7528\u6237\u5bf9\u201c\u53d9\u4e8b\u6027\u706f\u5149\u201d\u7684\u76f4\u89c9\u8f6c\u5316\u4e3a\u5173\u4e8e\u5149\u5982\u4f55\u5f71\u54cd\u6587\u5316\u9057\u4ea7\u7269\u54c1\u611f\u77e5\u7684\u53ef\u6d4b\u91cf\u8bba\u65ad\u3002\", \"evidence_homepage_zh\": \"\u611f\u77e5\u667a\u80fd\u6559\u6388\uff0c\u03c0-lab \u53ca\u6240\u5728\u5206\u90e8\u8d1f\u8d23\u4eba\uff1b\u7814\u7a76\u591a\u611f\u5b98\u4f53\u9a8c\u4e0e\u4ea7\u54c1\u3001\u5149\u3001\u6750\u6599\u4e0e\u7a7a\u95f4\u7684\u611f\u77e5\u4e0e\u8bbe\u8ba1\u3002\u53c2\u4e0e\u7814\u7a76\u9879\u76ee\u201cExplora\u2014\u2014\u901a\u8fc7\u4e3b\u52a8\u63a2\u7d22\uff08EXPLORAtion\uff09\u611f\u77e5\u6750\u6599\u3001\u7269\u4f53\u4e0e\u7a7a\u95f4\u201d\u3002\", \"evidence_papers_zh\": [\"\u300a\u7167\u660e\u6750\u6599\u4e0e\u5149\u7684\u7269\u8d28\u5316\u300b\uff08LS 2024\uff09\u2192 \u9752\u94dc\u5668\u8868\u9762\u7684\u535a\u7269\u9986\u7167\u660e\", \"\u53d8\u5316\u7684\u5149\u7167\u989c\u8272\u4f7f\u9759\u6001\u56fe\u50cf\u4ea7\u751f\u53d8\u5316\uff08i-Perception 2026\uff09\u2192 \u58c1\u753b\u4e0a\u7684\u52a8\u6001\u5149\", \"\u4f2a\u89e6\u89c9\u7167\u7247\u4ea4\u4e92\uff08ToH 2025\uff09\u2192 \u4ea4\u4e92\u4ecb\u5bfc\u7684\u611f\u77e5\"], \"evidence_projects_funding_zh\": \"\u4e3b\u9875\u5217\u6709Explora\u9879\u76ee\uff08\u5bf9\u6750\u6599/\u7269\u4f53/\u7a7a\u95f4\u7684\u4e3b\u52a8\u63a2\u7d22\uff09\u3002\u672a\u6838\u5b9e\u5230\u5f00\u653e\u7684\u535a\u58eb\u62db\u52df\u3002\", \"fit_to_user_zh\": \"\u7167\u660e\u4ea7\u54c1\u80cc\u666f\uff08\u914d\u5149\u5206\u6790\u3001DIALux\uff09+ \u624b\u52bf\u539f\u578b \u2192 \u5728\u4ea4\u4e92\u5149\u7167\u4e0b\u5bf9\u9057\u4ea7\u6587\u7269\u8fdb\u884c\\\"\u4e3b\u52a8\u63a2\u7d22\\\"\uff0c\u5951\u5408 Explora \u4e3b\u9898\u3002\", \"counterargument_risk_zh\": \"\u611f\u77e5\u79d1\u5b66\u5b9e\u9a8c\u5ba4\uff1a\u8981\u6c42\u5fc3\u7406\u7269\u7406\u5b66/\u5b9e\u9a8c\u4e25\u8c28\u6027\uff1b\u4ee3\u5c14\u592b\u7279\u7684 CSC \u8def\u7ebf\u4e0d\u786e\u5b9a\u4e14\u8d44\u52a9\u4e0d\u8db3\uff1b\u7ade\u4e89\u6fc0\u70c8\u3002\", \"email_hook_zh\": \"\u5c06\u201cExplora\u2014\u2014\u6750\u6599\u4e0e\u7269\u54c1\u7684\u4e3b\u52a8\u63a2\u7d22\u201d\u4e0e\u4e00\u9879\u7814\u7a76\u76f8\u7ed3\u5408\uff1a\u89c2\u4f17\u4ee5\u624b\u52bf\u5f15\u5bfc\u5149\u7ebf\u7167\u5c04\u9752\u94dc\u5668\uff0c\u6d4b\u91cf\u5176\u5bf9\u6750\u8d28/\u610f\u4e49\u7684\u611f\u77e5\u3002\", \"csc_note_zh\": \"TU Delft \u5728\u7528\u6237\u7684 2016 \u540d\u5355\u4e0a\uff0c\u4f46 2023 \u5e74\u6709\u62a5\u9053\u79f0\u5176\u5bf9\u62db\u6536 CSC \u535a\u58eb\u201c\u8d8a\u6765\u8d8a\u4e0d\u60c5\u613f\u201d\uff08https://nltimes.nl/2023/05/02/dutch-universities-reluctant-accept-chinese-scholarship-phd-students\uff09\uff0c\u4e14\u4e0d\u4e3a\u5956\u5b66\u91d1\u535a\u58eb\u63d0\u4f9b\u8865\u8d34\uff08https://ukrant.nl/magazine/international-scholarship-phds-have-to-take-on-extra-jobs-now-that-theyre-getting-less-money-than-expected/?lang=en\uff09\u3002\u6709\u8d44\u52a9\u7684\u535a\u58eb\u804c\u4f4d\uff1a\u672a\u6838\u5b9e\u5230\u3002\", \"csc_status_zh\": \"\u5df2\u6682\u505c\u6216\u505c\u6b62\"}, {\"name\": \"Georgios Triantafyllidis\", \"school_en\": \"Aalborg University (Copenhagen campus)\", \"school_zh\": \"\u5965\u5c14\u5821\u5927\u5b66\uff08\u54e5\u672c\u54c8\u6839\u6821\u533a\uff09\", \"country\": \"Denmark\", \"title\": \"\", \"unit\": \"Lighting Design Lab; Section for Media Technology, Department of Architecture, Design and Media Technology\", \"homepage\": \"https://vbn.aau.dk/en/persons/gt\", \"email\": null, \"relevance\": 8, \"claim\": \"AAU's Lighting Design Lab is where 'light as language' meets media technology and VR, making it a natural host for a PhD on gesture-driven narrative lighting in heritage spaces.\", \"evidence_homepage\": \"AAU portal: Associate Professor, Dept. of Architecture, Design and Media Technology; Lighting Design Lab; 25 projects incl. NATURE-FUTURES (PI, 12/2025\u201312/2028) and supervisor of PhD project on human-centric indoor environments (from 04/2026).\", \"evidence_papers\": [\"Light as visual language (Buildings 2024) \u2192 narrative lighting\", \"EEG lighting real vs. virtual (LS 2024) \u2192 user's VR lighting project\", \"Kindergarten lighting concepts (2022) \u2192 perception-led design concepts\"], \"evidence_projects_funding\": \"NATURE-FUTURES (PI, 2025-2028); PhD project supervision from 04/2026; co-PI with Ellen Kathrine Hansen on a 2026 lighting symposium project (portal).\", \"fit_to_user\": \"User's OSRAM/LEDVANCE product experience + VR collaborative lighting-design project + gesture prototypes.\", \"counterargument_risk\": \"Associate professor (may need a full-professor co-supervisor); CSC status at AAU now unclear given Danish knowledge-security debates; Lighting Design Lab skews toward wellbeing/daylight rather than heritage.\", \"email_hook\": \"Lead with 'Light as a Form of Visual Language' and propose testing whether gesture-triggered light 'sentences' help visitors read a Dunhuang mural.\", \"sources\": [\"https://doi.org/10.3390/buildings14051385\"], \"verified\": true, \"csc_note\": \"Not on user's list. A 2023 report says Aalborg University has hosted CSC PhDs since 2009 (https://ing.dk/artikel/aarhus-university-investigate-chinese-students-contracts-after-discovery-loyalty-pledges-regime); current policy not verified. Portal lists him as supervisor on a PhD project started 01/04/2026.\", \"matched_keywords\": [\"narrative/storytelling lighting\", \"VR/AR/MR/XR\", \"HCI\", \"research-through-design\", \"digital media & interaction design\"], \"csc_status\": \"unknown\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": null, \"subject\": \"PhD enquiry: light as narrative language in heritage spaces\", \"body\": \"Dear Dr Triantafyllidis,\\n\\nYour paper \\\"Light as a Form of Visual Language Supporting Daily Schedules in Educational Spaces: A Design Framework\\\" gives me vocabulary for something I want to study in museums: light that does not only illuminate but says something. \\\"Decoding Lighting in Real and Virtual Environments: An EEG-Based Analysis of Emotional States\\\" is also close to my own VR lighting work.\\n\\nI come from lighting practice. Since November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales) and did light-distribution analysis for Abu Dhabi's Zayed Airport project, and at LEEDARSON led user research (Amazon data, DEMATEL) for smart-lighting lines selling over US$30M. So I can test light \\\"sentences\\\" in real hardware and with users; my office offers students for studies. My heritage prototype Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/) uses markerless MediaPipe hand tracking and Three.js particles: visitors brush dust from Dunhuang Buddha figures to reveal the gilded body.\\n\\nThe PhD I propose would extend \\\"light as visual language\\\" into gesture-driven narrative lighting for heritage spaces. A visitor's gesture would trigger light \\\"sentences\\\" that guide attention, give feedback and build symbolic links to an artefact such as a Dunhuang mural. I would compare these against static lighting in VR and in a physical setup, using measures of presence, cultural understanding and emotional response.\\n\\nMy background is design rather than computer science, and I have no first-author paper yet (I co-authored two MR papers). I would bring working prototypes, a granted MR invention patent and a Research-through-Design practice I intend to turn into empirical publications early on.\\n\\nOn funding: I understand Danish universities suspended CSC-funded PhD intake in 2023, so I would apply for a funded AAU PhD position rather than rely on CSC. Would you be open to supervising a project like this at the Lighting Design Lab, and do you expect a funded position in 2026\u201327 where it could fit?\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u201c\u5149\u4f5c\u4e3a\u89c6\u89c9\u8bed\u8a00\u201d\u4e0e\u4f60\u7684\u53d9\u4e8b\u7167\u660e\u51e0\u4e4e\u540c\u4e00\u6982\u5ff5\uff0cEEG \u865a\u5b9e\u7167\u660e\u8bba\u6587\u5bf9\u5e94\u4f60\u7684 VR \u7167\u660e\u8bfe\u9898\u3002\u53d1\u9001\u524d\u6838\u5b9e\uff1acsc.json \u663e\u793a\u4e39\u9ea6\u9ad8\u6821 2023 \u5e74\u8d77\u8054\u5408\u6682\u505c CSC\uff0c\u4fe1\u4e2d\u5df2\u6539\u4e3a\u7533\u8bf7\u5e26\u85aa\u5c97\u4f4d\uff1b\u4ed6\u662f\u526f\u6559\u6388\uff0c\u9700\u786e\u8ba4\u80fd\u5426\u4efb\u4e3b\u5bfc\u5e08\uff1bJSON \u4e2d\u65e0\u516c\u5f00\u90ae\u7bb1\uff0c\u9700\u5728 AAU VBN \u9875\u9762\u6216\u5b9e\u9a8c\u5ba4\u9875\u9762\u67e5\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff1a\u5149\u4f5c\u4e3a\u9057\u4ea7\u7a7a\u95f4\u4e2d\u7684\u53d9\u4e8b\u8bed\u8a00\", \"body_zh\": \"\u5c0a\u656c\u7684 Triantafyllidis \u535a\u58eb\uff1a\\n\\n\u60a8\u7684\u8bba\u6587 \\\"Light as a Form of Visual Language Supporting Daily Schedules in Educational Spaces: A Design Framework\\\"\uff08\u300a\u5149\u4f5c\u4e3a\u652f\u6301\u6559\u80b2\u7a7a\u95f4\u65e5\u5e38\u4f5c\u606f\u7684\u89c6\u89c9\u8bed\u8a00\uff1a\u4e00\u4e2a\u8bbe\u8ba1\u6846\u67b6\u300b\uff09\u4e3a\u6211\u60f3\u5728\u535a\u7269\u9986\u4e2d\u7814\u7a76\u7684\u4e1c\u897f\u63d0\u4f9b\u4e86\u8bcd\u6c47\uff1a\u4e0d\u4ec5\u7167\u660e\u3001\u800c\u4e14\u201c\u8a00\u8bf4\u201d\u7684\u5149\u3002\\\"Decoding Lighting in Real and Virtual Environments: An EEG-Based Analysis of Emotional States\\\"\uff08\u300a\u89e3\u7801\u771f\u5b9e\u4e0e\u865a\u62df\u73af\u5883\u4e2d\u7684\u7167\u660e\uff1a\u57fa\u4e8e\u8111\u7535\u7684\u60c5\u7eea\u72b6\u6001\u5206\u6790\u300b\uff09\u4e5f\u4e0e\u6211\u81ea\u5df1\u7684 VR \u7167\u660e\u5de5\u4f5c\u5f88\u63a5\u8fd1\u3002\\n\\n\u6211\u6765\u81ea\u7167\u660e\u5b9e\u8df5\u9886\u57df\u3002\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u62c5\u4efb\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff08\u4e9a\u9a6c\u900a\u6570\u636e\u3001DEMATEL\uff09\uff0c\u8fd9\u4e9b\u4ea7\u54c1\u7ebf\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u56e0\u6b64\uff0c\u6211\u80fd\u5728\u771f\u5b9e\u786c\u4ef6\u4e0a\u3001\u4e0e\u7528\u6237\u4e00\u8d77\u6d4b\u8bd5\u5149\u7684\u201c\u53e5\u5b50\u201d\uff1b\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u4e3a\u7814\u7a76\u63d0\u4f9b\u5b66\u751f\u3002\u6211\u7684\u9057\u4ea7\u539f\u578b Stone Reveal\uff08\u300a\u77f3\u50cf\u663e\u73b0\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\u4f7f\u7528\u65e0\u6807\u8bb0\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\u548c Three.js \u7c92\u5b50\uff1a\u89c2\u4f17\u62c2\u53bb\u6566\u714c\u4f5b\u50cf\u4e0a\u7684\u5c18\u571f\uff0c\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\\n\\n\u6211\u63d0\u51fa\u7684\u535a\u58eb\u7814\u7a76\u5c06\u628a\u201c\u5149\u4f5c\u4e3a\u89c6\u89c9\u8bed\u8a00\u201d\u62d3\u5c55\u5230\u9762\u5411\u9057\u4ea7\u7a7a\u95f4\u7684\u624b\u52bf\u9a71\u52a8\u53d9\u4e8b\u7167\u660e\u3002\u89c2\u4f17\u7684\u624b\u52bf\u4f1a\u89e6\u53d1\u5149\u7684\u201c\u53e5\u5b50\u201d\uff0c\u5f15\u5bfc\u6ce8\u610f\u529b\u3001\u63d0\u4f9b\u53cd\u9988\uff0c\u5e76\u4e0e\u6566\u714c\u58c1\u753b\u7b49\u6587\u7269\u5efa\u7acb\u8c61\u5f81\u8054\u7cfb\u3002\u6211\u5c06\u5728 VR \u548c\u5b9e\u4f53\u88c5\u7f6e\u4e2d\u628a\u8fd9\u4e9b\u65b9\u5f0f\u4e0e\u9759\u6001\u7167\u660e\u8fdb\u884c\u6bd4\u8f83\uff0c\u6d4b\u91cf\u4e34\u573a\u611f\u3001\u6587\u5316\u7406\u89e3\u548c\u60c5\u7eea\u53cd\u5e94\u3002\\n\\n\u6211\u7684\u80cc\u666f\u662f\u8bbe\u8ba1\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u662f\u4e24\u7bc7 MR \u8bba\u6587\u7684\u5408\u8457\u8005\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879 MR \u9886\u57df\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u5957\u8bbe\u8ba1\u7814\u7a76\u6cd5\uff08RtD\uff09\u5b9e\u8df5\uff0c\u6211\u6253\u7b97\u5728\u65e9\u671f\u5c31\u628a\u5b83\u8f6c\u5316\u4e3a\u5b9e\u8bc1\u7814\u7a76\u8bba\u6587\u3002\\n\\n\u5173\u4e8e\u8d44\u52a9\uff1a\u6211\u4e86\u89e3\u5230\u4e39\u9ea6\u5404\u5927\u5b66\u81ea 2023 \u5e74\u8d77\u6682\u505c\u62db\u6536\u56fd\u5bb6\u7559\u5b66\u57fa\u91d1\u59d4\uff08CSC\uff09\u8d44\u52a9\u7684\u535a\u58eb\u751f\uff0c\u56e0\u6b64\u6211\u4f1a\u7533\u8bf7\u5965\u5c14\u5821\u5927\u5b66\uff08AAU\uff09\u5e26\u8d44\u52a9\u7684\u535a\u58eb\u5c97\u4f4d\uff0c\u800c\u4e0d\u4f9d\u8d56 CSC\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u5728\u7167\u660e\u8bbe\u8ba1\u5b9e\u9a8c\u5ba4\uff08Lighting Design Lab\uff09\u6307\u5bfc\u8fd9\u6837\u7684\u9879\u76ee\uff1f\u60a8\u9884\u8ba1 2026\u201327 \u5e74\u662f\u5426\u4f1a\u6709\u9002\u5408\u7684\u5e26\u8d44\u52a9\u5c97\u4f4d\uff1f\\n\\n\u6b64\u81f4\\n\u656c\u793c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Julieta Cignacco\", \"status\": \"current\", \"start_year\": 2025, \"graduation_year\": null, \"thesis_title\": \"Perceiving cultural heritage in darkness: A lighting design approach\uff08Art of Darkness as Cultural Heritage of Urban Landscape\uff09\", \"topic_zh\": \"\u9ed1\u6697\u4e2d\u7684\u6587\u5316\u9057\u4ea7\u611f\u77e5\uff1a\u4eae\u5ea6\u6307\u6807\u4e0e\u7167\u660e\u8bbe\u8ba1\uff08\u4e0eHvass\u3001Hansen\u8054\u5408\uff09\", \"url\": \"https://vbn.elsevierpure.com/en/persons/julieta-cignacco/\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"A. Heyselberghs\", \"status\": \"current\", \"start_year\": 2026, \"graduation_year\": null, \"thesis_title\": \"Data-driven methods for design and operation of human-centric energy-optimized indoor environments\", \"topic_zh\": \"\u4ee5\u4eba\u4e3a\u672c\u3001\u80fd\u8017\u4f18\u5316\u5ba4\u5185\u73af\u5883\u7684\u6570\u636e\u9a71\u52a8\u65b9\u6cd5\uff08\u4e0eC. Berger\u8054\u5408\uff09\", \"url\": \"https://vbn.aau.dk/en/persons/gt\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Stavroula Angelaki\", \"status\": \"current\", \"start_year\": null, \"graduation_year\": null, \"thesis_title\": \"\uff08\u513f\u7ae5\u7a7a\u95f4\u7167\u660e\u4e0e\u2018\u5149\u4f5c\u4e3a\u89c6\u89c9\u8bed\u8a00\u2019\uff1b\u73b0\u4e3aKTH\u5efa\u7b51\u5b66\u9662\u7167\u660e\u5206\u90e8\u535a\u58eb\u751f\uff0cTriantafyllidis\u4e3a\u5408\u8457\u8005\u2014\u2014\u662f\u5426\u4e3a\u5176\u5bfc\u5e08\u672a\u6838\u5b9e\uff09\", \"topic_zh\": \"\u5e7c\u513f\u56ed\u7167\u660e\u8bbe\u8ba1\u4e0e\u5149\u4f5c\u4e3a\u65e5\u7a0b\u89c6\u89c9\u8bed\u8a00\", \"url\": \"https://www.arch.kth.se/en/avdelningar/architectural-design\", \"now\": null, \"background\": \"AAU\u7167\u660e\u8bbe\u8ba1\u7855\u58eb\uff082018\u20132020\uff09\uff0c\u5ba4\u5185\u5efa\u7b51\u5e08\", \"chinese_or_csc\": null}, {\"name\": \"Tsampikos Kounalakis\", \"status\": \"alumni\", \"start_year\": null, \"graduation_year\": null, \"thesis_title\": \"Activity recognition using combined SIFT and L1 techniques\uff08Brunel\u5927\u5b66\uff0cTriantafyllidis\u4e3a\u672c\u5730\u5bfc\u5e08\uff09\", \"topic_zh\": \"SIFT+L1\u6d3b\u52a8\u8bc6\u522b\", \"url\": \"https://homes.create.aau.dk/gt\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}], \"total_estimate\": \"\u5728\u8bfb 2\uff08AAU\uff09\uff1bAngelaki\u4e3a\u5408\u4f5c\u8005\uff08KTH\u5728\u8bfb\uff09\uff0c\u6bd5\u4e1a\u751f\u53ef\u6838\u5b9e1\uff08Brunel\u8054\u5408\u6307\u5bfc\uff09\", \"student_pattern_zh\": \"\u7167\u660e\u8bbe\u8ba1+\u8ba1\u7b97\u673a\u89c6\u89c9\uff1a\u9057\u4ea7\u591c\u666f\u4e0e\u9ed1\u6697\u611f\u77e5\u3001\u663c\u591c\u8282\u5f8b\u7167\u660e\u3001EEG\u6bd4\u8f83\u771f\u5b9e\u4e0e\u865a\u62df\u7167\u660e\u611f\u77e5\u3001\u6570\u636e\u9a71\u52a8\u5ba4\u5185\u73af\u5883\u3002\u65b9\u6cd5\u4e3a\u7167\u660e\u5b9e\u9a8c\u5ba4\u6d4b\u91cf+\u7528\u6237\u611f\u77e5\u5b9e\u9a8c+VR\u4eff\u771f\uff0c\u4ecb\u4e8e\u5de5\u7a0b\u4e0e\u8bbe\u8ba1\u4e4b\u95f4\u3002\", \"design_background_ok_zh\": \"\u53cb\u597d\uff1aAAU\u7167\u660e\u8bbe\u8ba1\u7855\u58eb\u672c\u8eab\u9762\u5411\u5efa\u7b51/\u8bbe\u8ba1\u80cc\u666f\uff1bAngelaki\u4e3a\u5ba4\u5185\u5efa\u7b51\u5e08\u51fa\u8eab\uff1bCignacco\u5728\u7167\u660e\u8bbe\u8ba1\u7ec4\u505a\u9057\u4ea7\u7167\u660e\u3002\", \"chinese_students_zh\": \"\u672a\u53d1\u73b0\u4e2d\u56fd\u5b66\u751f\u6216CSC\u8bb0\u5f55\u3002\", \"implication_zh\": \"\u76f4\u63a5\u5bf9\u53e3\u2018\u53d9\u4e8b\u7167\u660e+\u6587\u5316\u9057\u4ea7\u2019\uff1aCignacco\u7684\u2018\u9ed1\u6697\u4e2d\u7684\u6587\u5316\u9057\u4ea7\u611f\u77e5\u2019\u4e0e\u6b27\u76dfArt of Darkness\u9879\u76ee\u662f\u6700\u4f73\u5f15\u7528\u5bf9\u8c61\uff1b\u53ef\u63d0\u51fa\u2018\u624b\u52bf\u9a71\u52a8\u7684\u975e\u9057\u591c\u95f4\u53d9\u4e8b\u7167\u660e\u2019\u3002\u98ce\u9669\uff1a\u4e39\u9ea6PhD\u4e3a\u5e26\u85aa\u804c\u4f4d\uff0c\u540d\u989d\u968f\u9879\u76ee\u5f00\u653e\uff0c\u9700\u76efAAU\u62db\u8058\uff1b\u4ed6\u662f\u526f\u6559\u6388\uff0c\u4e3b\u5bfc\u5e08\u5e38\u7531Ellen Kathrine Hansen\u7b49\u62c5\u4efb\u3002\", \"sources\": [\"https://vbn.aau.dk/en/persons/gt\", \"https://vbn.elsevierpure.com/en/persons/julieta-cignacco/\", \"https://homes.create.aau.dk/gt\", \"https://orcid.org/0000-0002-0495-777X\"], \"searched\": [\"AAU VBN Pure\u4eba\u5458\u4e0ePhD\u9879\u76ee\", \"Lighting Design Lab\u7ec4\u7ec7\u9875\", \"\u4e2a\u4ebaCV\u9875\", \"ORCID\", \"LinkedIn\", \"web\u641c\u7d22\"]}, \"country_zh\": \"\u4e39\u9ea6\", \"unit_zh\": \"\u7167\u660e\u8bbe\u8ba1\u5b9e\u9a8c\u5ba4\uff1b\u5a92\u4f53\u6280\u672f\u7cfb\uff0c\u5efa\u7b51\u3001\u8bbe\u8ba1\u4e0e\u5a92\u4f53\u6280\u672f\u5b66\u9662\", \"claim_zh\": \"AAU \u7684\u7167\u660e\u8bbe\u8ba1\u5b9e\u9a8c\u5ba4\u662f\u201c\u5149\u4f5c\u4e3a\u8bed\u8a00\u201d\u4e0e\u5a92\u4f53\u6280\u672f\u548c VR \u4ea4\u6c47\u4e4b\u5904\uff0c\u5929\u7136\u9002\u5408\u627f\u63a5\u5173\u4e8e\u9057\u4ea7\u7a7a\u95f4\u4e2d\u624b\u52bf\u9a71\u52a8\u53d9\u4e8b\u7167\u660e\u7684\u535a\u58eb\u8bfe\u9898\u3002\", \"evidence_homepage_zh\": \"\u5965\u5c14\u5821\u5927\u5b66\uff08AAU\uff09\u95e8\u6237\uff1a\u5efa\u7b51\u3001\u8bbe\u8ba1\u4e0e\u5a92\u4f53\u6280\u672f\u7cfb\u526f\u6559\u6388\uff1b\u7167\u660e\u8bbe\u8ba1\u5b9e\u9a8c\u5ba4\uff1b25 \u4e2a\u9879\u76ee\uff0c\u5305\u62ec NATURE-FUTURES\uff08\u9879\u76ee\u8d1f\u8d23\u4eba\uff0c2025/12\u20132028/12\uff09\uff0c\u5e76\u62c5\u4efb\u4ee5\u4eba\u4e3a\u672c\u5ba4\u5185\u73af\u5883\u535a\u58eb\u9879\u76ee\u5bfc\u5e08\uff08\u81ea 2026/04 \u8d77\uff09\u3002\", \"evidence_papers_zh\": [\"\u5149\u4f5c\u4e3a\u89c6\u89c9\u8bed\u8a00\uff08Buildings 2024\uff09\u2192 \u53d9\u4e8b\u6027\u7167\u660e\", \"\u771f\u5b9e\u4e0e\u865a\u62df\u7167\u660e\u4e0b\u7684\u8111\u7535\uff08LS 2024\uff09\u2192 \u7528\u6237\u7684 VR \u7167\u660e\u9879\u76ee\", \"\u5e7c\u513f\u56ed\u7167\u660e\u6982\u5ff5\uff082022\uff09\u2192 \u4ee5\u611f\u77e5\u4e3a\u5bfc\u5411\u7684\u8bbe\u8ba1\u6982\u5ff5\"], \"evidence_projects_funding_zh\": \"NATURE-FUTURES\uff08\u9996\u5e2d\u7814\u7a76\u5458\uff0c2025\u20132028\uff09\uff1b\u81ea 2026 \u5e74 4 \u6708\u8d77\u6307\u5bfc\u535a\u58eb\u9879\u76ee\uff1b\u4e0e Ellen Kathrine Hansen \u5171\u540c\u4e3b\u6301 2026 \u5e74\u7167\u660e\u7814\u8ba8\u4f1a\u9879\u76ee\uff08\u636e\u95e8\u6237\u7f51\u7ad9\uff09\u3002\", \"fit_to_user_zh\": \"\u7528\u6237\u5728 OSRAM/LEDVANCE \u7684\u4ea7\u54c1\u7ecf\u9a8c + VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u9879\u76ee + \u624b\u52bf\u539f\u578b\u3002\", \"counterargument_risk_zh\": \"\u526f\u6559\u6388\uff08\u53ef\u80fd\u9700\u8981\u6b63\u6559\u6388\u62c5\u4efb\u8054\u5408\u5bfc\u5e08\uff09\uff1b\u9274\u4e8e\u4e39\u9ea6\u5173\u4e8e\u77e5\u8bc6\u5b89\u5168\u7684\u8ba8\u8bba\uff0c\u56fd\u5bb6\u7559\u5b66\u57fa\u91d1\u59d4\u5728 AAU \u7684\u73b0\u72b6\u4e0d\u660e\uff1b\u7167\u660e\u8bbe\u8ba1\u5b9e\u9a8c\u5ba4\u504f\u5411\u5065\u5eb7/\u65e5\u5149\uff0c\u800c\u975e\u9057\u4ea7\u3002\", \"email_hook_zh\": \"\u4ee5\u300a\u5149\u4f5c\u4e3a\u4e00\u79cd\u89c6\u89c9\u8bed\u8a00\u300b\u5f00\u7bc7\uff0c\u63d0\u51fa\u68c0\u9a8c\u624b\u52bf\u89e6\u53d1\u7684\u5149\\\"\u53e5\u5b50\\\"\u80fd\u5426\u5e2e\u52a9\u89c2\u4f17\u89e3\u8bfb\u6566\u714c\u58c1\u753b\u3002\", \"csc_note_zh\": \"\u4e0d\u5728\u7528\u6237\u540d\u5355\u4e2d\u30022023 \u5e74\u4e00\u7bc7\u62a5\u9053\u79f0\u5965\u5c14\u5821\u5927\u5b66\u81ea 2009 \u5e74\u8d77\u63a5\u6536 CSC \u535a\u58eb\u751f\uff08https://ing.dk/artikel/aarhus-university-investigate-chinese-students-contracts-after-discovery-loyalty-pledges-regime\uff09\uff1b\u73b0\u884c\u653f\u7b56\u672a\u6838\u5b9e\u3002\u95e8\u6237\u7f51\u7ad9\u5217\u5176\u4e3a 2026 \u5e74 4 \u6708 1 \u65e5\u542f\u52a8\u7684\u4e00\u4e2a\u535a\u58eb\u9879\u76ee\u7684\u5bfc\u5e08\u3002\", \"csc_status_zh\": \"\u672a\u77e5\"}, {\"name\": \"Kim Halskov\", \"school_en\": \"Aarhus University\", \"school_zh\": \"\u5965\u80e1\u65af\u5927\u5b66\", \"country\": \"Denmark\", \"title\": \"\", \"unit\": \"CAVI \u2013 Centre for Advanced Visualisation and Interaction; Dept. of Digital Design and Information Studies\", \"homepage\": \"https://pure.au.dk/portal/en/persons/halskov%40cavi.au.dk\", \"email\": \"halskov@cavi.au.dk\", \"relevance\": 8, \"claim\": \"Halskov's CAVI work on ambient media that narrates historical places is the closest RtD precedent for 'narrative lighting in heritage spaces'.\", \"evidence_homepage\": \"Professor; CAVI and Participatory IT; Pure lists 180 publications, 8 projects, PhD supervision (4).\", \"evidence_papers\": [\"Soundscapes for historical buildings (DRS 2022) \u2192 ambient narration of heritage\", \"Sound-O-Matic (DIS 2025) \u2192 authoring tool for spatial media\", \"Thermal affective design space RtD (CHI 2026) \u2192 RtD method\"], \"evidence_projects_funding\": \"Pure: CAVI (2001\u2192), Centre for Participatory IT (2012\u2192), BICLabs. No open PhD call verified.\", \"fit_to_user\": \"Light as the visual counterpart of his sonic place-making; user's prototypes as RtD artefacts.\", \"counterargument_risk\": \"No CSC at AU since 2023 \u2014 needs an AU-funded scholarship (Faculty of Arts open call); senior professor, capacity unknown.\", \"email_hook\": \"Ask whether CAVI's sonic place-making approach for historical buildings could be paired with gesture-responsive light, citing the DRS 2022 paper.\", \"sources\": [\"https://cavi.au.dk/people\", \"https://www.au.dk/en/show/person/halskov@cavi.au.dk\"], \"verified\": true, \"csc_note\": \"CSC route closed: Aarhus University decided in March 2023 to stop admitting CSC-funded PhD students (https://omnibus.au.dk/en/archive/show/artikel/au-stopper-optaget-af-kinesiske-phd-studerende-der-har-underskrevet-troskabsed). Only AU-funded/open-call PhD scholarships remain.\", \"matched_keywords\": [\"research-through-design\", \"digital media & interaction design\", \"museum digital cultural heritage\", \"HCI\", \"embodied interaction\"], \"csc_status\": \"paused_or_stopped\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": \"halskov@cavi.au.dk\", \"subject\": \"PhD enquiry: gesture-responsive light as place-making in historical buildings\", \"body\": \"Dear Professor Halskov,\\n\\nYour DRS paper \\\"Soundscape design for historical buildings as a sonic place-making process\\\" frames ambient media as a way of narrating a historical place, and I would like to explore the visual counterpart of that idea: light. \\\"Constructing the Thermal Affective Design Space for Emotion Regulation: An Autoethnographic Research Through Design Inquiry\\\" also shows the kind of Research-through-Design inquiry I hope to learn.\\n\\nSince November 2025 I have directed the Digital ICH Design and Production Teaching and Research Office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting, supervising student 3D content production and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran nine product families at OSRAM/LEDVANCE (~100 SKUs, ~US$8M in sales) and did light-distribution analysis for Abu Dhabi's Zayed Airport project, and at LEEDARSON led user research (Amazon data, DEMATEL) for smart-lighting lines selling over US$30M. So I know how to make light work in real buildings; my office offers students for co-design and field studies. My recent prototypes use markerless hand tracking for heritage. In Bronze Heritage Gesture Interaction (https://cooleli.github.io/Portfolio-page/Bronze%20Heritage%20Gesture%20Interaction%20project/), five Chinese bronzes are rebuilt as Three.js particle clouds that visitors melt, rotate and reassemble with their hands, without headset or controlle");